// Package credentials loads sensitive values that must never be written
// to the GitOps repo. See docs/decisions/0012-platform-config-and-credentials.md
// in urbforge/urbex: environment variables take precedence, falling back
// to ~/.urbex/credentials.yaml.
//
// Some values are supplied by the user (Proxmox/Cloudflare tokens, age
// key); the platform secrets (admin passwords, Komodo API and onboarding
// keys, Gitea token) are generated by urbex bootstrap and persisted to the same file
// via Update.
package credentials

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"

	"gopkg.in/yaml.v3"
)

// Credentials holds secrets read from the environment or from
// ~/.urbex/credentials.yaml. Never log or serialize this back out, except
// through Update.
type Credentials struct {
	ProxmoxToken    string `yaml:"proxmoxToken,omitempty"`
	CloudflareToken string `yaml:"cloudflareToken,omitempty"`
	AgeKey          string `yaml:"ageKey,omitempty"`

	// Generated by urbex bootstrap.
	GiteaAdminPassword    string `yaml:"giteaAdminPassword,omitempty"`
	GiteaToken            string `yaml:"giteaToken,omitempty"`
	KomodoAdminPassword   string `yaml:"komodoAdminPassword,omitempty"`
	KomodoDBPassword      string `yaml:"komodoDbPassword,omitempty"`
	KomodoJWTSecret       string `yaml:"komodoJwtSecret,omitempty"`
	KomodoWebhookSecret   string `yaml:"komodoWebhookSecret,omitempty"`
	KomodoAPIKey          string `yaml:"komodoApiKey,omitempty"`
	KomodoAPISecret       string `yaml:"komodoApiSecret,omitempty"`
	KomodoOnboardingKey   string `yaml:"komodoOnboardingKey,omitempty"`
	KeycloakAdminPassword string `yaml:"keycloakAdminPassword,omitempty"`
	GrafanaAdminPassword  string `yaml:"grafanaAdminPassword,omitempty"`
}

// fields pairs every credential with its environment variable, so Load,
// fillFrom, and Env stay in sync as credentials are added.
func (c *Credentials) fields() []struct {
	env string
	ptr *string
} {
	return []struct {
		env string
		ptr *string
	}{
		{"URBEX_PROXMOX_TOKEN", &c.ProxmoxToken},
		{"URBEX_CLOUDFLARE_TOKEN", &c.CloudflareToken},
		{"URBEX_AGE_KEY", &c.AgeKey},
		{"URBEX_GITEA_ADMIN_PASSWORD", &c.GiteaAdminPassword},
		{"URBEX_GITEA_TOKEN", &c.GiteaToken},
		{"URBEX_KOMODO_ADMIN_PASSWORD", &c.KomodoAdminPassword},
		{"URBEX_KOMODO_DB_PASSWORD", &c.KomodoDBPassword},
		{"URBEX_KOMODO_JWT_SECRET", &c.KomodoJWTSecret},
		{"URBEX_KOMODO_WEBHOOK_SECRET", &c.KomodoWebhookSecret},
		{"URBEX_KOMODO_API_KEY", &c.KomodoAPIKey},
		{"URBEX_KOMODO_API_SECRET", &c.KomodoAPISecret},
		{"URBEX_KOMODO_ONBOARDING_KEY", &c.KomodoOnboardingKey},
		{"URBEX_KEYCLOAK_ADMIN_PASSWORD", &c.KeycloakAdminPassword},
		{"URBEX_GRAFANA_ADMIN_PASSWORD", &c.GrafanaAdminPassword},
	}
}

// Load reads credentials from environment variables first (URBEX_*, see
// fields), then fills in anything still missing from
// ~/.urbex/credentials.yaml if that file exists.
func Load() (*Credentials, error) {
	c := &Credentials{}
	for _, f := range c.fields() {
		*f.ptr = os.Getenv(f.env)
	}
	path, err := DefaultPath()
	if err != nil {
		return nil, err
	}
	fromFile, err := loadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return c, nil
		}
		return nil, err
	}
	c.fillFrom(fromFile)
	return c, nil
}

// DefaultPath returns ~/.urbex/credentials.yaml for the current user.
func DefaultPath() (string, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("determining home directory: %w", err)
	}
	return filepath.Join(home, ".urbex", "credentials.yaml"), nil
}

func loadFile(path string) (*Credentials, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var c Credentials
	if err := yaml.Unmarshal(data, &c); err != nil {
		return nil, fmt.Errorf("parsing %s: %w", path, err)
	}
	return &c, nil
}

func (c *Credentials) fillFrom(other *Credentials) {
	theirs := other.fields()
	for i, f := range c.fields() {
		if *f.ptr == "" {
			*f.ptr = *theirs[i].ptr
		}
	}
}

// Update applies change to both c and the credentials file (creating it
// with mode 0600 if needed), leaving every other value in the file as it
// was - values that came from the environment are not copied into it.
func (c *Credentials) Update(change func(*Credentials)) error {
	path, err := DefaultPath()
	if err != nil {
		return err
	}
	onDisk, err := loadFile(path)
	if os.IsNotExist(err) {
		onDisk = &Credentials{}
	} else if err != nil {
		return err
	}
	change(c)
	change(onDisk)
	data, err := yaml.Marshal(onDisk)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return err
	}
	if err := os.WriteFile(path, data, 0o600); err != nil {
		return err
	}
	// WriteFile keeps an existing file's mode; make sure it's private.
	return os.Chmod(path, 0o600)
}

// Get returns the credential whose environment variable is name, or ""
// if name isn't a known credential.
func (c *Credentials) Get(name string) string {
	for _, f := range c.fields() {
		if f.env == name {
			return *f.ptr
		}
	}
	return ""
}

// Set sets the credential whose environment variable is name; unknown
// names are ignored.
func (c *Credentials) Set(name, value string) {
	for _, f := range c.fields() {
		if f.env == name {
			*f.ptr = value
		}
	}
}

// Env returns URBEX_*=value entries for the given credentials, for
// passing secrets to child processes (e.g. Ansible's lookup('env')) without
// writing them to files.
func (c *Credentials) Env(names ...string) []string {
	want := make(map[string]bool, len(names))
	for _, n := range names {
		want[n] = true
	}
	var env []string
	for _, f := range c.fields() {
		if want[f.env] {
			env = append(env, f.env+"="+*f.ptr)
		}
	}
	return env
}

// RandomSecret returns a random 48-hex-character secret, safe to use
// unquoted in env files and shell arguments.
func RandomSecret() (string, error) {
	b := make([]byte, 24)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

// MissingForProvisioning reports which credentials required for the
// Terraform+Ansible provisioning phase of urbex bootstrap are missing.
// The Cloudflare token is needed only by a later phase (tunnel setup)
// and is checked separately once that is implemented; platform secrets
// are generated by bootstrap itself.
func (c *Credentials) MissingForProvisioning() []string {
	var missing []string
	if c.ProxmoxToken == "" {
		missing = append(missing, "URBEX_PROXMOX_TOKEN (or proxmoxToken in ~/.urbex/credentials.yaml)")
	}
	if c.AgeKey == "" {
		missing = append(missing, "URBEX_AGE_KEY (or ageKey in ~/.urbex/credentials.yaml)")
	}
	return missing
}

// MissingForPlatform reports which bootstrap-generated credentials needed
// to set up and run project rollouts (Gitea, Komodo) are missing - i.e.
// whether urbex bootstrap has completed on this machine.
func (c *Credentials) MissingForPlatform() []string {
	var missing []string
	for _, f := range []struct {
		env string
		v   string
	}{
		{"URBEX_GITEA_TOKEN", c.GiteaToken},
		{"URBEX_KOMODO_API_KEY", c.KomodoAPIKey},
		{"URBEX_KOMODO_API_SECRET", c.KomodoAPISecret},
		{"URBEX_KOMODO_ONBOARDING_KEY", c.KomodoOnboardingKey},
		{"URBEX_KOMODO_WEBHOOK_SECRET", c.KomodoWebhookSecret},
	} {
		if f.v == "" {
			missing = append(missing, f.env)
		}
	}
	return missing
}
